@lru_cache(maxsize=1)
def _shapes():
    with np.load(io.BytesIO(base64.b85decode(_DATA))) as data:
        return tuple(data[f'link{i}'].copy() for i in range(8))

def visual_robot_arm_mask(points,tcp,joints):
    """Include link7 and published visual shells omitted by collision meshes."""
    base=tcp@np.linalg.inv(panda_tcp_pose(joints))
    rotation,position=base[:3,:3].copy(),base[:3,3].copy()
    poses=[(rotation.copy(),position.copy())]
    for offset,fixed,angle in zip(_POSITIONS,_FIXED_ROTATIONS,joints):
        position+=rotation@offset
        c,s=np.cos(angle),np.sin(angle)
        rotation=rotation@fixed@np.array([[c,-s,0.],[s,c,0.],[0.,0.,1.]])
        poses.append((rotation.copy(),position.copy()))
    result=np.zeros(len(points),dtype=bool)
    for (rotation,position),eq,(low,high) in zip(poses,_shapes(),_BOUNDS):
        local=(points-position)@rotation
        ids=np.flatnonzero(np.all((local>=low)&(local<=high),axis=1))
        result[ids]|=np.all(local[ids]@eq[:,:3].T+eq[:,3]<.004,axis=1)
    return result
